# -*- coding: utf-8 -*-
"""Curriculum data for CAC. 702 Adolescent Development (1.6 units)."""

PARTS = [
    ("I", "Foundations of Adolescent Development",
     "The intellectual scaffolding of the course: what adolescence is, how it has been studied, which theories explain it, how evidence is built, and how developmental knowledge becomes professional competence in the counselling room."),
    ("II", "Biological Development and Health",
     "The body in transition: puberty, the developing brain, sleep, sexuality, body image, movement, illness and disability, and what each means for adolescents and for the counsellors who serve them."),
    ("III", "Cognitive Development and Learning",
     "The mind in transition: abstract thought, executive function, decision making, language, motivation, digital cognition, giftedness and neurodiversity across the adolescent years."),
    ("IV", "Identity, Self and Social Cognition",
     "The person in formation: identity, self-concept, gender, cultural identity, moral growth, empathy, autonomy, and the possible selves adolescents imagine and pursue."),
    ("V", "Emotional and Relational Development",
     "The relational world: emotion, attachment, parents, peers, romance, digital social life, belonging, and the changing bonds through which adolescents grow."),
    ("VI", "Risk, Resilience and Psychosocial Challenges",
     "When development is stressed: coping, risk-taking, substances, conduct, bullying, self-harm, adversity, and the protective processes that carry adolescents through."),
    ("VII", "Diversity, Culture and Life Contexts",
     "Development in context: culture and migration, socioeconomic opportunity, family transitions, affirming practice, inclusion, vocation, and the global realities of contemporary adolescence."),
    ("VIII", "Development-Informed Counselling Practice",
     "From knowledge to practice: developmental assessment, formulation, matched intervention, family and school partnership, prevention, ethics, safeguarding, and the assessment of learning in CAC. 702."),
]

